// app.js

// Register Service Worker

// Start screen button
const imgButton = document.getElementById('play-button');

imgButton.style.cursor = 'pointer';
imgButton.addEventListener('click', () => {
  const screen = document.getElementById('start-screen');
  screen.style.display = 'none';
});

// Function to hide the loading indicator.
// This should be called when your WASM game is fully initialized and ready to display.
window.gameLoaded = function() {
    const loadingIndicator = document.getElementById('loading-indicator');
    if (loadingIndicator) {
        loadingIndicator.style.opacity = '0';
        // Remove from DOM after transition to prevent interaction issues
        setTimeout(() => {
            if (loadingIndicator.parentNode) {
                 loadingIndicator.parentNode.removeChild(loadingIndicator);
            }
        }, 500); // Match transition duration
    }
    console.log("Game loaded, hiding loading indicator.");
};

// --- Integration with Emscripten (or similar WASM loaders) ---
// If your 'asteroids.js' is generated by Emscripten, it often defines a 'Module' object.
// You can hook into its lifecycle.

// Ensure Module object exists or create a placeholder
var Module = typeof Module !== 'undefined' ? Module : {};

// Emscripten's callback for when the runtime is initialized.
// This is often the point where WASM is compiled and ready, but not necessarily when
// your game's specific assets are loaded or the first frame is ready.
Module.onRuntimeInitialized = function() {
    console.log("Emscripten runtime initialized.");
    // It's often better to call window.gameLoaded() from a more specific point
    // in your game's own loading sequence if onRuntimeInitialized is too early.
    // For a basic setup, this might be sufficient.
    // If your game has its own main() or similar entry point that signals readiness,
    // call window.gameLoaded() from there.
     window.gameLoaded(); 
};

// Fallback: If the game doesn't explicitly call window.gameLoaded() or use Module.onRuntimeInitialized,
// you might hide the loader after a timeout, but this is not ideal.
// setTimeout(() => {
//     if (document.getElementById('loading-indicator')) { // Check if still present
//         console.warn("Loading indicator fallback: Hiding after timeout. Game should ideally call window.gameLoaded().");
//         window.gameLoaded();
//     }
// }, 5000); // Adjust timeout as needed

console.log("app.js loaded. Waiting for game to signal readiness or Emscripten runtime initialization.");
